import React from 'react';
import { templateFn } from '@igblsln/control';
import { MODULE_NAME } from '../constants';

const layoutTemplateFn = (page: string) => templateFn(`/${MODULE_NAME}/${page}`);

const sectionPath = (section: string) =>
  `layout/${section.toLowerCase().replace(/\s+/g, '-')}`;

const childPath = (section: string, child: string) =>
  `${sectionPath(section)}/${child.toLowerCase().replace(/\s+/g, '-')}`;

const boldNavigatorHeader = (item: any, options: any) => (
  <a className={options.className} onClick={options.onClick} style={{ fontWeight: 700 }}>
    <span className={options.labelClassName} style={{ fontWeight: 700 }}>{item.label}</span>
  </a>
);

const sectionItems = [
  'Sump',
  'OHT',
  // 'Floor Structure',
  'Roof',
  'Floor Column',
  { label: 'Staircase Room', template: layoutTemplateFn(childPath('Staircase', 'Stair Room')) },
  { label: 'Head Room', template: layoutTemplateFn(childPath('Staircase', 'Head Room')) },
  { label: 'Lift Footing', template: layoutTemplateFn(childPath('Lift', 'Lift Footing')) },
  { label: 'Lift Shaft', template: layoutTemplateFn(childPath('Lift', 'Lift Shaft')) },
  { label: 'Machine Room', template: layoutTemplateFn(childPath('Lift', 'Machine Room')) },
  'Apartment',
  'OTS',
].map((section: any) => typeof section === 'string'
  ? { label: section, template: layoutTemplateFn(sectionPath(section)) }
  : section);

const routes = [
  {
    label: <strong>Sections</strong> as any,
    icon: 'pi ml-3',
    className: 'section-models-header',
    template: boldNavigatorHeader,
    expanded: true,
    items: [
      {
        label: 'Main',
        icon: 'pi ml-3',
        className: 'section-models-main',
        expanded: true,
        items: sectionItems,
      },
    ],
  },
];

export const portionItems = [
  {
    label: <strong>Portions</strong> as any,
    icon: 'pi ml-3',
    className: 'portions-header',
    template: boldNavigatorHeader,
    expanded: true,
    items: [
      { label: 'Beam Bit' },
      { label: 'Slab' },
      { label: 'Column Footing' },
      { label: 'Column Bit' },
      { label: 'Room' },
      { label: 'Lintel Bit' },
      { label: 'Loft Bit' },
      { label: 'Sun Shade' },
      { label: 'Staircase Slab' },
    ],
  },
];

export default routes;
