import React, { useState } from 'react';
import { PORTIONS_SCREEN3_CONFIGS, PORTIONS_SCREEN3_GROUPS } from './config';
import { buildBlankSectionRows, GROUPED_ROD_TAB_ROWS, toGroupedRodTab, SectionModelRow } from './sectionConfig';
import RowTable from './RowTable';
import { PORTIONS_TABLE_STYLES, PORTIONS_LAYOUT_STYLES } from './styles';

type Props = { portionType: string; modelName: string };

// Temporary metric definitions until the portion-specific metric data is supplied.
const MOCK_METRICS: Record<string, [string, string][]> = {
  'beam-bit': [['Shuttering', 'Area'], ['Concrete', 'Volume']],
  slab: [['Shuttering', 'Area'], ['Concrete', 'Volume']],
  'column-footing': [
    ['Excavation Time', 'Duration'],
    ['Marking Time', 'Duration'],
    ['Shuttering', 'Area'],
    ['PCC', 'Volume'],
    ['Concrete', 'Volume'],
  ],
  'column-portion': [['Shuttering', 'Area'], ['Concrete', 'Volume']],
  room: [['Room Area', 'Area'], ['Wall Area', 'Area'], ['Concrete', 'Volume']],
  'lintel-bit': [['Lintel Length', 'Length'], ['Shuttering', 'Area'], ['Concrete', 'Volume']],
  'loft-bit': [['Loft Area', 'Area'], ['Shuttering', 'Area'], ['Concrete', 'Volume']],
};

const PortionTables = ({ portionType, modelName }: Props) => {
  const portions = PORTIONS_SCREEN3_GROUPS.reduce<{
    key: string;
    label: string;
    sectionType: string;
  }[]>((items, group) => items.concat(group.items), []);
  const portion = portions.find(item => item.key === portionType);
  const configs: Record<string, any> = PORTIONS_SCREEN3_CONFIGS;
  const config = portion && (configs[portionType] || configs[portion.sectionType]);
  const [rowsByTable, setRowsByTable] = useState<Record<string, SectionModelRow[]>>({});
  const [metricQuantities, setMetricQuantities] = useState<Record<string, string>>({});
  const [metricUoms, setMetricUoms] = useState<Record<string, string>>({});
  const [rodValues, setRodValues] = useState<Record<string, string>>({});
  const [activeTab, setActiveTab] = useState<'Input' | 'Metrics' | 'Rod'>('Input');
  if (!config) return <div>No portion tables available.</div>;

  const tabs = config.tabs.map((tab: any) => GROUPED_ROD_TAB_ROWS[tab.id] ? toGroupedRodTab(tab, GROUPED_ROD_TAB_ROWS[tab.id]()) : tab);
  const inputTabs = tabs.filter((tab: any) => ['property', 'measurement', 'metrics', 'input'].some(key => tab.title.toLowerCase().includes(key)));
  const inputTab = inputTabs[0];
  const rodDescriptionGroups: Record<string, string[]> = {
    'beam-bit': ['Main Rod', 'Ring Rod'],
    'loft-bit': ['Main Rod', 'Ring Rod'],
    slab: ['Main Rod', 'Distributor Rod'],
    'column-footing': ['Main Rod', 'Distributor Rod'],
    'column-portion': ['Main Rod', 'Ring Rod'],
    room: [],
    'lintel-bit': ['Main Rod', 'Ring Rod'],
  };
  const rodDescriptions = rodDescriptionGroups[portionType] || [];
  const inputTables = inputTab ? [
    ...(!inputTab.hideMainTable ? [inputTab] : []),
    ...(inputTab.children || []).filter((child: any) => !child.id.includes('derived')),
  ] : [];
  const renderTable = (table: any, editable: boolean) => {
    const rows = rowsByTable[table.id] || buildBlankSectionRows(table);
    return <RowTable key={table.id} title={table.title} segmentName={modelName} portionName={config.label} section={table} rows={rows} disabled={!editable}
      onCellUpdate={(rowId, field, value) => setRowsByTable(current => ({ ...current, [table.id]: rows.map(row => row.id === rowId ? { ...row, [field]: value } : row) }))}
      onGroupAdd={entity => setRowsByTable(current => ({ ...current, [table.id]: [...rows, { id: `${table.id}-${Date.now()}-${rows.length}`, entity }] }))}
      onGroupDelete={(_entity, rowId) => setRowsByTable(current => ({ ...current, [table.id]: rows.filter(row => row.id !== rowId) }))}
    />;
  };

  return <div className="estimation-portion-tables portions-screen3-shell portions-screen-shell">
    <style>{PORTIONS_TABLE_STYLES}{PORTIONS_LAYOUT_STYLES}{`
      .estimation-portion-tables.portions-screen-shell{padding:0;min-width:0;min-height:0;overflow:auto}
      .estimation-portion-tables .portions-screen-content{min-height:0;border:0!important;border-radius:0;padding:0;overflow:visible}
      .estimation-portion-tables .portion-tab-content{padding:14px!important}
      .estimation-portion-tables .estimation-layout-tabs{padding-top:8px!important;padding-left:14px!important}
      .estimation-portion-tables .portion-metrics-table{width:88%;border-collapse:collapse;margin:0}.estimation-portion-tables .portion-metrics-table th,.estimation-portion-tables .portion-metrics-table td{border:1px solid #222;padding:7px 10px;text-align:center;vertical-align:middle}.estimation-portion-tables .portion-metrics-table th{background:#999696;color:#fff}.estimation-portion-tables .portion-measurement-label{display:inline-flex;align-items:center;margin-right:10px;font-weight:500}.estimation-portion-tables .portion-metrics-quantity-cell{display:inline-flex;align-items:center;justify-content:center;gap:6px}.portion-metrics-quantity{width:70px;box-sizing:border-box;padding:5px;border:1px solid #cbd5e1}.portion-metrics-uom{height:29px;padding:3px 6px;border:1px solid #cbd5e1;background:#fff}
      .estimation-portion-tables .portion-rod-table{width:88%;table-layout:fixed;border-collapse:collapse;margin:0 0 14px}.estimation-portion-tables .portion-rod-table th,.estimation-portion-tables .portion-rod-table td{width:16.666%;height:28px;border:1px solid #222;padding:7px 8px;text-align:left}.estimation-portion-tables .portion-rod-table th{background:#999696;color:#fff;text-align:center}.estimation-portion-tables .portion-rod-cell{display:flex;align-items:center;gap:7px}.estimation-portion-tables .portion-rod-cell input,.estimation-portion-tables .portion-rod-cell select{height:30px;box-sizing:border-box;border:1px solid #cbd5e1;background:#fff;padding:4px 8px}.estimation-portion-tables .portion-rod-cell input{min-width:0;flex:1}.estimation-portion-tables .portion-rod-cell select{min-width:76px}.estimation-portion-tables .portion-rod-unit{display:inline-flex;align-items:center;justify-content:center;height:30px;min-width:76px;padding:4px 8px;border:1px solid #cbd5e1;background:#f8fafc;font-weight:600;box-sizing:border-box}
    `}</style>
    <div className="portions-screen-content">
      <div className="estimation-layout-tabs portion-tabs" role="tablist" aria-label="Portion model tables">
        {(['Input', 'Metrics', 'Rod'] as const).map(tab => <button key={tab} type="button" role="tab" aria-selected={activeTab === tab} className={`estimation-layout-tab${activeTab === tab ? ' active' : ''}`} onClick={() => setActiveTab(tab)}>{tab}</button>)}
      </div>
      <div className="estimation-layout-data portion-tab-content" role="tabpanel">
        {activeTab === 'Input' && <div className="section-model-stack">{inputTables.map((table: any) => renderTable(table, true))}</div>}
        {activeTab === 'Metrics' && <table className="portion-metrics-table"><colgroup><col style={{width:"15%"}} /><col style={{width:"25%"}} /><col style={{width:"24%"}} /><col style={{width:"24%"}} /></colgroup><thead><tr><th>Metrics</th><th>Measurement / Quantity</th><th aria-label="Empty column"></th><th aria-label="Empty column"></th></tr></thead><tbody>{(MOCK_METRICS[portionType] || []).map(([metric, measurementType]) => <tr key={metric}><td>{metric}</td><td><span className="portion-measurement-label">{measurementType}</span><span className="portion-metrics-quantity-cell"><input className="portion-metrics-quantity" value={metricQuantities[metric] || ''} onChange={event => setMetricQuantities(current => ({ ...current, [metric]: event.target.value }))} /><select className="portion-metrics-uom" value={metricUoms[metric] || ''} onChange={event => setMetricUoms(current => ({ ...current, [metric]: event.target.value }))}><option value="">UOM</option><option value="m">m</option><option value="Nos">Nos</option><option value="Sq.Ft">Sq.Ft</option><option value="ft">ft</option></select></span></td><td aria-hidden="true"></td><td aria-hidden="true"></td></tr>)}</tbody></table>}
        {activeTab === 'Rod' && <table className="portion-rod-table"><colgroup>{[0, 1, 2, 3, 4, 5].map(column => <col key={column} style={{ width: '16.666%' }} />)}</colgroup><thead><tr><th>Description</th><th>Rod Size</th><th>Length</th><th>Count</th><th aria-label="Empty column"></th><th aria-label="Empty column"></th></tr></thead><tbody>{rodDescriptions.length ? rodDescriptions.reduce<React.ReactElement[]>((rows, description: string, groupIndex: number) => rows.concat([0, 1].map((rowIndex: number) => { const rowKey = `${groupIndex}-${rowIndex}`; return <tr key={`rod-${rowKey}`}>{rowIndex === 0 && <td rowSpan={2} className="portion-rod-description">{description}</td>}<td><div className="portion-rod-cell"><select value={rodValues[`rod-${rowKey}-size`] || ''} onChange={event => setRodValues(current => ({ ...current, [`rod-${rowKey}-size`]: event.target.value }))}><option value="">Select</option><option value="6">6</option><option value="8">8</option><option value="10">10</option><option value="12">12</option><option value="16">16</option></select><span className="portion-rod-unit">MM</span></div></td><td><div className="portion-rod-cell"><input value={rodValues[`rod-${rowKey}-length`] || ''} onChange={event => setRodValues(current => ({ ...current, [`rod-${rowKey}-length`]: event.target.value }))} /><select value={rodValues[`rod-${rowKey}-uom`] || ''} onChange={event => setRodValues(current => ({ ...current, [`rod-${rowKey}-uom`]: event.target.value }))}><option value="">UOM</option><option value="m">m</option><option value="ft">ft</option><option value="Sq.Ft">Sq.Ft</option></select></div></td><td><div className="portion-rod-cell"><input value={rodValues[`rod-${rowKey}-count`] || ''} onChange={event => setRodValues(current => ({ ...current, [`rod-${rowKey}-count`]: event.target.value }))} /><span className="portion-rod-unit">Nos</span></div></td><td aria-hidden="true"></td><td aria-hidden="true"></td></tr>; })), []) : <tr><td colSpan={6}>No rod groups configured for this portion.</td></tr>}</tbody></table>}
      </div>
    </div>
  </div>;
};

export default PortionTables;







