// Independent snapshot for estimation layout; copied from Portions 3 dependencies.
import React from 'react';
import { PORTION_CONFIGS } from './baseConfig';
import { UOM_OPTIONS } from './sectionConfig';

const PORTION_UOM_OPTIONS = [
  ...UOM_OPTIONS.filter((option) => option.value === 'Sq.Ft' || option.value === 'mtr' || option.value === 'ft')
  .map((option) => ({
    ...option,
    label: option.value === 'Sq.Ft' ? 'Sqfeet' : option.value === 'mtr' ? 'Meter' : 'Feet',
  })),
  { label: 'Inches', value: 'in' },
];
const ROD_SPACING_UOM_OPTIONS = [
  { label: 'Inches', value: 'in' },
  { label: 'MM', value: 'mm' },
];

const CIVIL_ROD_SIZE_OPTIONS = [6, 8, 10, 12, 16, 20, 25, 32, 40];

const portion = (key: string, label: string, sectionType: string) => ({
  key,
  label,
  sectionType,
});

export const PORTIONS_SCREEN3_GROUPS = [
  { key: 'beam-bit', label: 'Beam Bit', items: [portion('beam-bit', 'Beam Bit', 'beam-bit')] },
  { key: 'slab', label: 'Slab', items: [portion('slab', 'Slab', 'slab')] },
  { key: 'column-footing', label: 'Column Footing', items: [portion('column-footing', 'Column Footing', 'column-footing')] },
  { key: 'column-portion', label: 'Column Bit', items: [portion('column-portion', 'Column Bit', 'column-portion')] },
  { key: 'room', label: 'Room', items: [portion('room', 'Room', 'room')] },
  { key: 'lintel-bit', label: 'Lintel Bit', items: [portion('lintel-bit', 'Lintel Bit', 'beam-bit')] },
  { key: 'loft-bit', label: 'Loft Bit', items: [portion('loft-bit', 'Loft Bit', 'apartment')] },
];

const slabInputCell = (key: string) => (row: any, _rowIndex: number, updateCell: (key: string, value: any) => void, disabled: boolean) => (
  <input
    type="text"
    value={row[key] ?? ''}
    disabled={Boolean(disabled)}
    onChange={(event) => updateCell(key, event.target.value)}
    className="portion-slab-input"
    style={{ width: '100%' }}
  />
);

const slabInputColumn = (key: string, header: string) => ({
  key,
  header,
  width: '15%',
  renderCell: slabInputCell(key),
});

const slabInputWithUomColumn = (key: string, header: string, defaultUom = '', uomOptions = PORTION_UOM_OPTIONS) => ({
  key,
  header,
  width: '15%',
  renderCell: (row: any, rowIndex: number, updateCell: (key: string, value: any) => void, disabled: boolean) => (
    <div className="portion-slab-input-uom-cell">
      {slabInputCell(key)(row, rowIndex, updateCell, disabled)}
      <select
        value={row[`${key}Uom`] || defaultUom}
        disabled={Boolean(disabled)}
        onChange={(event) => updateCell(`${key}Uom`, event.target.value)}
        className={`portion-slab-uom${(row[`${key}Uom`] || defaultUom) ? '' : ' portion-slab-uom-placeholder'}`}
      >
        <option value="" disabled hidden>UOM</option>
        {uomOptions.map((option) => (
          <option key={option.value} value={option.value}>{option.label}</option>
        ))}
      </select>
    </div>
  ),
});

const fixedUomColumn = (
  key: string,
  header: string,
  uom: string,
  renderValue: (row: any, rowIndex: number, updateCell: (key: string, value: any) => void, disabled: boolean) => React.ReactNode = slabInputCell(key),
) => ({
  key,
  header,
  width: '15%',
  renderCell: (row: any, rowIndex: number, updateCell: (key: string, value: any) => void, disabled: boolean) => (
    <div className="portion-slab-input-uom-cell">
      {renderValue(row, rowIndex, updateCell, disabled)}
      <span className="portion-slab-uom portion-slab-fixed-uom" aria-label={`Unit of measure: ${uom}`}>{uom}</span>
    </div>
  ),
});

const rodSizeColumn = (key = 'rodSize') => fixedUomColumn(
  key,
  'Rod Size',
  'MM',
  (row: any, _rowIndex: number, updateCell: (key: string, value: any) => void, disabled: boolean) => (
    <select
      value={row[key] ?? ''}
      disabled={Boolean(disabled)}
      onChange={(event) => updateCell(key, event.target.value)}
      className="portion-slab-input portion-slab-compact-select"
      style={{ width: '100%' }}
    >
      <option value="" disabled hidden>Select</option>
      {CIVIL_ROD_SIZE_OPTIONS.map((size) => (
        <option key={size} value={size}>{size}</option>
      ))}
    </select>
  ),
);

const countColumn = (key = 'count') => fixedUomColumn(key, 'Count', 'Nos');

const spanPercentageColumn = (key = 'spanPercent') => fixedUomColumn(
  key,
  'Span Percentage',
  '%',
  (row: any, _rowIndex: number, updateCell: (key: string, value: any) => void, disabled: boolean) => (
    <input
      type="text"
      value={row[key] ?? ''}
      disabled={Boolean(disabled)}
      onChange={(event) => updateCell(key, event.target.value)}
      className="portion-slab-input"
      style={{ width: '100%' }}
    />
  ),
);

const slabUomColumn = (key: string) => ({
  key,
  header: 'UOM',
  width: '15%',
  renderCell: (row: any, _rowIndex: number, updateCell: (key: string, value: any) => void, disabled: boolean) => (
    <select
      value={row[key] ?? ''}
      disabled={Boolean(disabled)}
      onChange={(event) => updateCell(key, event.target.value)}
      className={`portion-slab-uom${row[key] ? '' : ' portion-slab-uom-placeholder'}`}
      style={{ width: '100%' }}
    >
      <option value="" disabled hidden>UOM</option>
      {PORTION_UOM_OPTIONS.map((option) => (
        <option key={option.value} value={option.value}>{option.label}</option>
      ))}
    </select>
  ),
});

const groupedPortionConfig = (label: string, entityGroups: any[], initialRows: any[]) => ({
  ...PORTION_CONFIGS.slab,
  label,
  value: label.toLowerCase().replace(/\s+/g, '-'),
  tabs: PORTION_CONFIGS.slab.tabs.map((tab: any) => {
    if (tab.id !== 'slab-property') return tab;
    return {
      ...tab,
      children: tab.children.map((child: any) => {
        if (child.id !== 'slab-property-input') return child;
        return {
          ...child,
          columns: [],
          entityGroups,
          initialRows,
        };
      }),
    };
  }),
});

const rodColumns = [
  rodSizeColumn(),
  slabInputWithUomColumn('spacing', 'Spacing', '', ROD_SPACING_UOM_OPTIONS),
  slabInputWithUomColumn('rodLength', 'Length'),
  countColumn(),
];

const parameterPairsForColumns = (columns: { key: string; header: string }[]) => columns.map((column) => ({
  value: slabInputColumn(column.key, column.header),
  uom: slabUomColumn(`${column.key}Uom`),
}));

const roomRows = (entity: string, columns: { key: string; header: string }[]) => ({
  entity,
  parameterColumns: [],
  parameterPairs: parameterPairsForColumns(columns),
});

const blankRoomRow = (entity: string, columns: { key: string; header: string }[]) => {
  const row: Record<string, string> = { entity };
  columns.forEach((column: { key: string; header: string }) => {
    row[column.key] = '';
    row[`${column.key}Uom`] = '';
  });
  return row;
};

