// Tank and floor opening sections use the same grouped input presentation as
// the portion screen, while retaining their section-specific measurements.
const sectionRodGroup = (entity: string, ring = false) => ({
  entity,
  parameterColumns: ring
    ? [rodSizeColumn(), slabInputWithUomColumn('rodLength', 'Length'), slabInputWithUomColumn('spacing', 'Spacing', '', ROD_SPACING_UOM_OPTIONS)]
    : [rodSizeColumn(), countColumn()],
  showActions: true,
});

const sectionRodRow = (entity: string, ring = false) => ring
  ? { entity, rodSize: '', rodLength: '', spacing: '' }
  : { entity, rodSize: '', count: '' };

const groupedSectionInputConfig = (
  label: string,
  fields: { key: string; header: string }[],
  rodGroups: { entity: string; ring?: boolean }[] = [{ entity: 'Main Rod' }, { entity: 'Distributor Rod' }],
) => groupedPortionConfig(
  label,
  [{ entity: 'Dimension', parameterColumns: [], parameterPairs: parameterPairsForColumns(fields) }, ...rodGroups.map(group => sectionRodGroup(group.entity, group.ring))],
  [
    { entity: 'Dimension', ...fields.reduce((row, field) => ({ ...row, [field.key]: '', [`${field.key}Uom`]: '' }), {} as Record<string, string>) },
    ...rodGroups.flatMap(group => [sectionRodRow(group.entity, group.ring), sectionRodRow(group.entity, group.ring)]),
  ],
);

