export const UNIT_SYSTEM_OPTIONS = [
    { label: 'Meter', value: 'METRIC' },
    { label: 'Feet', value: 'IMPERIAL' },
];
export const DEFAULT_UNIT_SYSTEM = 'IMPERIAL';
const PROJECT_UNIT_SYSTEM_STORAGE_KEY = 'estimation_unit_system_by_project';
export const MEASUREMENT_FIELD_KEYS = new Set([
    'length',
    'breadth',
    'width',
    'height',
    'depth',
    'thickness',
    'distance',
    'spreadSpan',
    'skirtingLength',
    'wallLength',
    'pccThickness',
]);
export const isMeasurementFieldKey = (key) => !!key && MEASUREMENT_FIELD_KEYS.has(key);
export const getMeasurementUomLabel = (unitSystem) => unitSystem === 'METRIC' ? 'Meter' : 'Feet';
export function convertMetricToDecimal(meter, mm) {
    const safeMeter = Number.isFinite(meter) ? Math.max(0, meter) : 0;
    const safeMm = Number.isFinite(mm) ? Math.max(0, mm) : 0;
    return safeMeter + safeMm / 1000;
}
export function convertDecimalToMetric(decimal) {
    const safe = Number.isFinite(decimal) ? Math.max(0, decimal) : 0;
    const meter = Math.floor(safe);
    let mm = Math.round((safe - meter) * 1000);
    if (mm >= 1000) {
        return { meter: meter + Math.floor(mm / 1000), mm: mm % 1000 };
    }
    return { meter, mm };
}
export function convertImperialToDecimal(feet, inches) {
    const safeFeet = Number.isFinite(feet) ? Math.max(0, feet) : 0;
    const safeInches = Number.isFinite(inches) ? Math.max(0, inches) : 0;
    return safeFeet + safeInches / 12;
}
export function convertDecimalToImperial(decimal) {
    const safe = Number.isFinite(decimal) ? Math.max(0, decimal) : 0;
    const feet = Math.floor(safe);
    let inches = Math.round((safe - feet) * 12);
    if (inches >= 12) {
        return { feet: feet + Math.floor(inches / 12), inches: inches % 12 };
    }
    return { feet, inches };
}
export function parseStoredMeasurement(value) {
    if (value === '' || value === null || value === undefined) {
        return null;
    }
    const normalized = String(value).replace(/,/g, '').trim();
    if (!normalized) {
        return null;
    }
    const num = Number(normalized);
    return Number.isFinite(num) ? num : null;
}
export function formatMeasurement(value, unitSystem) {
    const decimal = parseStoredMeasurement(value);
    if (decimal === null) {
        return '';
    }
    if (unitSystem === 'METRIC') {
        const { meter, mm } = convertDecimalToMetric(decimal);
        return `${meter} Meter ${mm} MM`;
    }
    const { feet, inches } = convertDecimalToImperial(decimal);
    return `${feet} Feet ${inches} Inches`;
}
export function validateMetricParts(meter, mm) {
    if (!Number.isFinite(meter) || meter < 0) {
        return { valid: false, message: 'Meter must be 0 or greater' };
    }
    if (!Number.isFinite(mm) || mm < 0) {
        return { valid: false, message: 'MM must be 0 or greater' };
    }
    if (mm >= 1000) {
        return { valid: false, message: 'MM must be less than 1000' };
    }
    return { valid: true };
}
export function validateImperialParts(feet, inches) {
    if (!Number.isFinite(feet) || feet < 0) {
        return { valid: false, message: 'Feet must be 0 or greater' };
    }
    if (!Number.isFinite(inches) || inches < 0) {
        return { valid: false, message: 'Inches must be 0 or greater' };
    }
    if (inches >= 12) {
        return { valid: false, message: 'Inches must be less than 12' };
    }
    return { valid: true };
}
export function normalizeLegacyMeasurementValue(value, unitSystem) {
    const parsed = parseStoredMeasurement(value);
    if (parsed === null) {
        return null;
    }
    return parsed;
}
export function shouldInterpretAsRawSubunit(value, _unitSystem) {
    if (!Number.isFinite(value) || !Number.isInteger(value)) {
        return false;
    }
    // Whole numbers at or above 100 are treated as raw subunits (mm / inches).
    return value >= 100;
}
export function interpretAsSubunit(value, unitSystem) {
    const parsed = parseStoredMeasurement(value);
    if (parsed === null) {
        return null;
    }
    if (!shouldInterpretAsRawSubunit(parsed, unitSystem)) {
        return parsed;
    }
    if (unitSystem === 'METRIC') {
        return parsed / 1000;
    }
    if (unitSystem === 'IMPERIAL') {
        return parsed / 12;
    }
    return parsed;
}
/** Converts explicit raw subunit entry (mm or inches) to decimal meters/feet. */
export function convertRawSubunitInputToDecimal(value, unitSystem) {
    const parsed = parseStoredMeasurement(value);
    if (parsed === null) {
        return null;
    }
    if (unitSystem === 'METRIC') {
        return parsed / 1000;
    }
    if (unitSystem === 'IMPERIAL') {
        return parsed / 12;
    }
    return parsed;
}
export function resolveMeasurementDecimal(value, unitSystem, interpretAsSubunitMode = false) {
    const parsed = parseStoredMeasurement(value);
    if (parsed === null) {
        return null;
    }
    if (!interpretAsSubunitMode) {
        return parsed;
    }
    return interpretAsSubunit(parsed, unitSystem);
}
export function loadProjectUnitSystem(projectKey) {
    if (!projectKey) {
        return DEFAULT_UNIT_SYSTEM;
    }
    try {
        const raw = localStorage.getItem(PROJECT_UNIT_SYSTEM_STORAGE_KEY);
        if (!raw) {
            return DEFAULT_UNIT_SYSTEM;
        }
        const map = JSON.parse(raw);
        return map[String(projectKey)] === 'METRIC' ? 'METRIC' : DEFAULT_UNIT_SYSTEM;
    }
    catch (_a) {
        return DEFAULT_UNIT_SYSTEM;
    }
}
export function saveProjectUnitSystem(projectKey, unitSystem) {
    if (!projectKey) {
        return;
    }
    try {
        const raw = localStorage.getItem(PROJECT_UNIT_SYSTEM_STORAGE_KEY);
        const map = raw ? JSON.parse(raw) : {};
        map[String(projectKey)] = unitSystem;
        localStorage.setItem(PROJECT_UNIT_SYSTEM_STORAGE_KEY, JSON.stringify(map));
    }
    catch (_a) {
        // ignore persistence errors in mock/local mode
    }
}
