import { api, tags } from '@igblsln/store'

const API_PATH = '/dashboard/'
const CHATBOT_PATH = '/chatbot/'


export interface DashboardSummary {
  active_projects: number
  pending_pos: number
  vendor_pending_payments: number
  contractor_pending_payments: number
}

export type ChatbotAction = 'next_page' | 'confirm' | 'cancel'


export interface DisplayColumn {
  key: string
  label: string
  format?: string 
}

export type DisplayRow = Record<string, string | number | boolean | null>

export interface ChatbotDisplay {
  kind: 'table' | 'card'
  title?: string
  total?: number
  columns: DisplayColumn[]
  rows: DisplayRow[]
  has_more?: boolean
}

export interface ChatbotResponse {
  conversation_id: string
  status: 'message' | 'needs_confirmation'
  reply: string
  confirm?: string | null
  display?: ChatbotDisplay | null
}
export interface ChatbotRequest {
  message?: string
  conversation_id?: string
  action?: ChatbotAction
}

export const dashboardApi = api.injectEndpoints({
  overrideExisting: false,
  endpoints: (build) => ({
    getDashboardSummary: build.query<DashboardSummary, void>({
      query: () => ({
        url: API_PATH,
      }),
      providesTags: [{ type: tags.DASHBOARD, id: 'SUMMARY' }],
    }),
    sendChatMessage: build.mutation<ChatbotResponse, ChatbotRequest>({
      query: (body) => ({
        url: CHATBOT_PATH,
        method: 'POST',
        body,
      }),
    }),
  }),
})

export const {
  useGetDashboardSummaryQuery,
  useSendChatMessageMutation,
} = dashboardApi

export const {
  endpoints: { getDashboardSummary , sendChatMessage },
} = dashboardApi
