// Independent snapshot for estimation layout; copied from Portions 3 dependencies.
import React from 'react';
import {
  GridColumn,
  GridSectionConfig,
  SectionModelRow,
  renderSectionTitle,
} from './sectionConfig';

const noopUpdate = () => {};
const noopDelete = () => {};

type RowTableProps = {
  title: string;
  segmentName: string;
  portionName?: string;
  rows: SectionModelRow[];
  section: GridSectionConfig;
  disabled?: boolean;
  onCellUpdate?: (rowId: string, key: string, value: any) => void;
  onGroupAdd?: (entity: string) => void;
  onGroupDelete?: (entity: string, rowId: string) => void;
};

const isGroupStart = (row: SectionModelRow, rowIndex: number, keys: string[], keyIndex: number) => {
  if (rowIndex === 0) return true;
  for (let index = 0; index <= keyIndex; index += 1) {
    if (row[keys[index]]) return true;
  }
  return false;
};

const computeGroupSpans = (rows: SectionModelRow[], keys: string[]) => {
  const spanMaps: Record<string, Record<number, number>> = {};
  keys.forEach((key, keyIndex) => {
    spanMaps[key] = {};
    rows.forEach((row, rowIndex) => {
      if (!isGroupStart(row, rowIndex, keys, keyIndex)) {
        spanMaps[key][rowIndex] = 0;
        return;
      }
      let span = 1;
      while (rowIndex + span < rows.length && !isGroupStart(rows[rowIndex + span], rowIndex + span, keys, keyIndex)) {
        span += 1;
      }
      spanMaps[key][rowIndex] = span;
    });
  });
  return spanMaps;
};

const renderEntityGroupedTable = ({ section, rows, portionName, segmentName, onCellUpdate, onGroupAdd, onGroupDelete, disabled }: RowTableProps) => {
  const groups = section.entityGroups || [];
  const fixedColumns = groups[0]?.fixedColumns || [];
  const hasActions = groups.some((group) => group.showActions);
  const rowsByEntity = groups.map((group) => ({
    group,
    rows: rows.filter((row) => row.entity === group.entity),
  }));
  const update = onCellUpdate || noopUpdate;

  return (
    <div className="section-model-table-content" style={{ marginTop: '12px' }}>
      <div className="section-model-table-shell section-model-entity-grouped-shell" style={section.tableWidth ? { width: section.tableWidth } : undefined}>
        <table className={`section-model-table section-model-entity-grouped-table${fixedColumns.length ? '' : ' section-model-entity-grouped-table-no-fixed'}${hasActions ? ' section-model-entity-grouped-table-actions' : ''}`}>
          <colgroup>
            <col style={{ width: '16%' }} />
            <col style={{ width: hasActions ? '67.2%' : (fixedColumns.length ? '68%' : '84%') }} />
            {fixedColumns.map((column) => <col key={column.key} style={{ width: '8%' }} />)}
            {hasActions && <><col style={{ width: '8.4%' }} /><col style={{ width: '8.4%' }} /></>}
          </colgroup>
          <thead>
            <tr>
              <th style={{ textAlign: 'center' }} colSpan={2 + fixedColumns.length + (hasActions ? 2 : 0)}>{portionName || segmentName}</th>
            </tr>
          </thead>
          <tbody>
            {rowsByEntity.map(({ group, rows: groupRows }, groupIndex) => {
              const parameterColumns = group.parameterColumns;
              const parameterPairs = group.parameterPairs || [];
              const visibleRows = groupRows.length > 0 ? groupRows : [{ id: `${section.id}-${group.entity}`, entity: group.entity }];
              const usesParameterPairs = parameterPairs.length > 0;
              const paddedParameterPairs = [
                ...parameterPairs,
                ...Array.from({ length: Math.max(3, Math.ceil(parameterPairs.length / 3) * 3) - parameterPairs.length }, () => null),
              ];
              const paddedParameterColumns: Array<GridColumn | null> = [
                ...parameterColumns,
                ...Array.from({ length: Math.max(0, 4 - parameterColumns.length) }, () => null),
              ];
              const entityRowSpan = usesParameterPairs ? visibleRows.length : visibleRows.length + 1;
              const entityStripeClass = groupIndex % 2 === 0 ? 'section-model-entity-group-even' : 'section-model-entity-group-odd';
              return (
                <React.Fragment key={group.entity}>
                  {groupIndex > 0 && (
                    <tr className="section-model-entity-group-spacer" aria-hidden="true">
                      <td colSpan={2 + fixedColumns.length + (hasActions ? 2 : 0)} />
                    </tr>
                  )}
                  <tr className={`section-model-entity-group-subheader ${entityStripeClass}`}>
                    <td rowSpan={entityRowSpan} className={`section-model-entity-cell${usesParameterPairs ? ' section-model-nonrod-entity-cell' : ''}`} style={{ textAlign: 'center', verticalAlign: 'middle' }}>
                      <div className="section-model-entity-cell-header">Entity</div>
                      <div className="section-model-entity-cell-name" style={{ display: 'inline-block', width: '100%', textAlign: 'center' }}>{group.entity}</div>
                    </td>
                    <td className="section-model-entity-param-cell" colSpan={hasActions && !group.showActions ? 3 : undefined}>
                      <div className={usesParameterPairs ? `section-model-entity-param-pair-grid${paddedParameterPairs.length > 3 ? ' section-model-entity-param-pair-grid-with-break' : ''}` : 'section-model-entity-param-grid'} style={{ gridTemplateColumns: usesParameterPairs ? 'repeat(3, minmax(0, 1fr))' : 'repeat(4, minmax(0, 1fr))' }}>
                        {usesParameterPairs ? paddedParameterPairs.map((pair, pairIndex) => pair ? (
                          <div className={`section-model-entity-param-pair section-model-entity-param-inline${pairIndex >= 3 ? ' section-model-entity-param-row-break' : ''}`} key={pair.value.key}>
                            <span className="section-model-entity-param-inline-label">{pair.value.header}</span>
                            <div className="section-model-entity-param-value section-model-entity-param-combined-value">
                              <div className="portion-slab-input-uom-cell">
                                {pair.value.renderCell(visibleRows[0], 0, (key, value) => update(visibleRows[0].id, key, value), disabled ?? false, noopDelete, visibleRows)}
                                {pair.uom.renderCell(visibleRows[0], 0, (key, value) => update(visibleRows[0].id, key, value), disabled ?? false, noopDelete, visibleRows)}
                              </div>
                            </div>
                          </div>
                        ) : (
                          <div className={`section-model-entity-param-pair section-model-entity-param-inline${pairIndex >= 3 ? ' section-model-entity-param-row-break' : ''}`} key={`empty-pair-${pairIndex}`} aria-hidden="true">
                            <span className="section-model-entity-param-inline-label section-model-entity-param-empty" />
                            <div className="section-model-entity-param-value section-model-entity-param-combined-value section-model-entity-param-empty" />
                          </div>
                        )) : paddedParameterColumns.map((column, columnIndex) => column ? <div className="section-model-entity-param-header" key={column.key}>{column.header}</div> : <div className="section-model-entity-param-header section-model-entity-param-empty" key={`empty-header-${columnIndex}`} aria-hidden="true" />)}
                      </div>
                    </td>
                    {fixedColumns.map((column) => <th key={column.key}>{column.header}</th>)}
                    {hasActions && group.showActions && (
                      <th className="section-model-action-header" colSpan={2}>
                        <div className="section-model-action-header-grid">
                          <span>Delete</span>
                          <span>Add</span>
                        </div>
                      </th>
                    )}
                  </tr>
                  {visibleRows.slice(usesParameterPairs ? 1 : 0).map((row, rowIndex) => {
                    const actualRowIndex = usesParameterPairs ? rowIndex + 1 : rowIndex;
                    return (
                    <tr key={row.id || `${group.entity}-${rowIndex}`} className={`${entityStripeClass}${rowIndex > 0 ? ' section-model-entity-continuation-row' : ''}`}>
                      <td className="section-model-entity-param-cell">
                        <div className={usesParameterPairs ? `section-model-entity-param-pair-grid${paddedParameterPairs.length > 3 ? ' section-model-entity-param-pair-grid-with-break' : ''}` : 'section-model-entity-param-grid'} style={{ gridTemplateColumns: usesParameterPairs ? 'repeat(3, minmax(0, 1fr))' : 'repeat(4, minmax(0, 1fr))' }}>
                          {usesParameterPairs ? paddedParameterPairs.map((pair, pairIndex) => pair ? (
                            <div className={`section-model-entity-param-pair${pairIndex >= 5 ? ' section-model-entity-param-row-break' : ''}`} key={pair.value.key}>
                              <div className="section-model-entity-param-value section-model-entity-param-combined-value">
                                <div className="portion-slab-input-uom-cell">
                                  {pair.value.renderCell(row, actualRowIndex, (key, value) => update(row.id, key, value), disabled ?? false, noopDelete, visibleRows)}
                                  {pair.uom.renderCell(row, actualRowIndex, (key, value) => update(row.id, key, value), disabled ?? false, noopDelete, visibleRows)}
                                </div>
                              </div>
                            </div>
                          ) : (
                            <div className={`section-model-entity-param-pair${pairIndex >= 5 ? ' section-model-entity-param-row-break' : ''}`} key={`empty-pair-value-${pairIndex}`} aria-hidden="true">
                              <div className="section-model-entity-param-value section-model-entity-param-combined-value section-model-entity-param-empty" />
                            </div>
                          )) : paddedParameterColumns.map((column, columnIndex) => column ? (
                            <div className="section-model-entity-param-value" key={column.key}>
                              {column.renderCell(row, actualRowIndex, (key, value) => update(row.id, key, value), disabled ?? false, noopDelete, visibleRows)}
                            </div>
                          ) : <div className="section-model-entity-param-value section-model-entity-param-empty" key={`empty-value-${columnIndex}`} aria-hidden="true" />)}
                        </div>
                      </td>
                      {fixedColumns.map((column) => (
                        <td key={column.key}>
                          {column.renderCell(row, rowIndex, (key, value) => update(row.id, key, value), disabled ?? false, noopDelete, visibleRows)}
                        </td>
                      ))}
                      {hasActions && group.showActions && (
                        <>
                          <td className="section-model-row-delete-cell">
                            <button type="button" className="section-model-row-action section-model-row-delete" aria-label={`Delete ${group.entity} row`} title="Delete" disabled={disabled} onClick={() => onGroupDelete?.(group.entity, row.id)}><i className="pi pi-trash" aria-hidden="true" /></button>
                          </td>
                          {rowIndex === 0 && (
                            <td className="section-model-row-add-cell" rowSpan={visibleRows.length}>
                              {!disabled && <button type="button" className="section-model-row-action section-model-row-add" aria-label={`Add ${group.entity} row`} title="Add" onClick={() => onGroupAdd?.(group.entity)}><i className="pi pi-plus" aria-hidden="true" /></button>}
                            </td>
                          )}
                        </>
                      )}
                    </tr>
                    );
                  })}
                </React.Fragment>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
};

const RowTable = ({ title, segmentName, portionName, rows, section, disabled = false, onCellUpdate, onGroupAdd, onGroupDelete }: RowTableProps) => {
  if (section.entityGroups?.length) {
    return renderEntityGroupedTable({ title, segmentName, portionName, rows, section, disabled, onCellUpdate, onGroupAdd, onGroupDelete });
  }
  const workRowSpans: Record<number, number> = {};
  const actionRowSpans: Record<number, number> = {};
  const taskRowSpans: Record<number, number> = {};
  const itemSpecRowSpans: Record<number, number> = {};
  const workGroupRows: Record<number, number> = {};
  const isWorkItemSection = section.id.endsWith('-workitem') || section.id.endsWith('-roditem');
  const groupSpanKeys = section.rowSpanKeys || [];
  const groupSpanMaps = groupSpanKeys.length ? computeGroupSpans(rows, groupSpanKeys) : {};
  if (isWorkItemSection) {
    let workGroup = -1;
    rows.forEach((row, rowIndex) => {
      if (row.work) workGroup += 1;
      workGroupRows[rowIndex] = Math.max(workGroup, 0);
      if (!row.work) return;
      let span = 1;
      while (rowIndex + span < rows.length && !rows[rowIndex + span].work) span += 1;
      workRowSpans[rowIndex] = span;
      actionRowSpans[rowIndex] = span;
      for (let index = rowIndex + 1; index < rowIndex + span; index += 1) workRowSpans[index] = 0;
      for (let index = rowIndex + 1; index < rowIndex + span; index += 1) actionRowSpans[index] = 0;
    });

    rows.forEach((row, rowIndex) => {
      if (!row.task) return;
      let span = 1;
      while (rowIndex + span < rows.length && !rows[rowIndex + span].task && !rows[rowIndex + span].work) span += 1;
      taskRowSpans[rowIndex] = span;
      for (let index = rowIndex + 1; index < rowIndex + span; index += 1) taskRowSpans[index] = 0;
    });

    // Item Spec rowspan: span across all rows within the same task group (like Task column)
    let currentTask = '';
    let itemSpecStartIndex = -1;
    rows.forEach((row, rowIndex) => {
      // Reset when new Work
      if (row.work) {
        currentTask = '';
        itemSpecStartIndex = -1;
      }
      // New Task starts - start itemSpec span from this row
      if (row.task) {
        currentTask = row.task;
        itemSpecStartIndex = rowIndex;
        itemSpecRowSpans[rowIndex] = 1; // will be extended below
      }
      // Continuation row within same task - extend itemSpec span
      else if (currentTask && row.task === '' && !row.work) {
        if (itemSpecStartIndex >= 0) {
          itemSpecRowSpans[itemSpecStartIndex] += 1;
          itemSpecRowSpans[rowIndex] = 0;
        }
      }
      // Task ended (next row has new task or work) - finalize
      const nextRow = rows[rowIndex + 1];
      if (currentTask && (nextRow?.task || nextRow?.work)) {
        currentTask = '';
        itemSpecStartIndex = -1;
      }
    });
  }

  return (
    <div className={`section-model-section-card${section.id.startsWith('bedroom-') || section.id.startsWith('bathroom-') ? ' section-model-plain' : ''}`}>
      {!section.hideTableTitle && (
        <div className="section-model-section-header">
          <div>
            {!section.titleRenderer && <div className="section-model-section-title">{title}</div>}
            {section.titleRenderer && (
              <div
                className="section-model-section-subtitle"
                style={section.tableWidth ? { width: section.tableWidth } : undefined}
              >
                {renderSectionTitle(section, segmentName)}
              </div>
            )}
          </div>
        </div>
      )}

      <div className="section-model-table-content" style={{ marginTop: '12px' }}>
        <div className={`section-model-table-shell${groupSpanKeys.length ? ' section-model-grouped-shell' : ''}`} style={section.tableWidth ? { width: section.tableWidth } : undefined}>
          <table className={`section-model-table${groupSpanKeys.length ? ' section-model-grouped-table' : ''}`}>
            <colgroup>
              {section.columns.map((column) => (
                <col key={column.key} style={{ width: column.width }} />
              ))}
            </colgroup>
            <thead>
              <tr>
                {section.columns.map((column) => (
                  <th key={column.key} style={{ textAlign: column.align || 'left', fontWeight: 'bold', fontSize: '16px', padding: '12px 8px', borderBottom: '2px solid #000' }}>
                    {column.header}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody style={{ borderTop: 'none' }}>
              {rows.length === 0 ? (
                <tr>
                  <td colSpan={section.columns.length} className="section-model-empty-row">
                    No rows configured.
                  </td>
                </tr>
              ) : (
                rows.map((row, rowIndex) => (
                  <tr key={row.id} className={isWorkItemSection
                    ? `${row.work ? 'work-group-start ' : ''}${workGroupRows[rowIndex] % 2 === 0 ? 'work-group-even' : 'work-group-odd'}`
                    : (rowIndex % 2 === 0 ? 'row-even' : 'row-odd')}>
                    {section.columns.map((column) => {
                      if (groupSpanKeys.includes(column.key) && groupSpanMaps[column.key]?.[rowIndex] === 0) return null;
                      if (column.key === 'work' && workRowSpans[rowIndex] === 0) return null;
                      if (column.key === 'task' && taskRowSpans[rowIndex] === 0) return null;
                      if (column.key === 'itemSpec' && itemSpecRowSpans[rowIndex] === 0) return null;
                      if (column.key === 'action' && actionRowSpans[rowIndex] === 0) return null;
                      const groupedSpan = groupSpanKeys.includes(column.key) ? groupSpanMaps[column.key]?.[rowIndex] : undefined;
                      const taskSpan = column.key === 'task' ? taskRowSpans[rowIndex] || 1 : undefined;
                      const itemSpecSpan = column.key === 'itemSpec' ? itemSpecRowSpans[rowIndex] || 1 : undefined;
                      const workItemSpan = column.key === 'work' || column.key === 'action'
                        ? (column.key === 'work' ? workRowSpans[rowIndex] : actionRowSpans[rowIndex]) || 1
                        : undefined;
                      return <td key={column.key} rowSpan={groupedSpan || workItemSpan || taskSpan || itemSpecSpan} style={{ textAlign: column.align || 'left' }}>
                        {column.renderCell(row, rowIndex, onCellUpdate ? (key: string, value: any) => onCellUpdate(row.id, key, value) : noopUpdate, disabled, noopDelete, rows)}
                      </td>;
                    })}
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export const SectionModelRowTable = RowTable;
export default RowTable;
