import React, { useMemo } from 'react';
import { Navigate, Route, Routes, useLocation, useNavigate, useSearchParams } from 'react-router-dom';
import { getMappedPortionTypes } from '../config';
import { MODULE_NAME } from '../constants';
import { ModuleLayout, NoMatch } from '@igblsln/control';
import routes, { portionItems } from './routes';
import MainPage from '../pages/Main';
import { selectSelectedBlock, selectSelectedProject, setSelectedBlockReducer, useAppDispatch, useAppSelector, useBlocksForProjectQuery } from '@igblsln/store';
import { PanelMenu } from 'primereact/panelmenu';

const portionKeyForLabel = (label: string) => label === 'Column Bit' ? 'column-portion' : label.toLowerCase().replace(/\s+/g, '-');

const BlockNavigationItem = ({ item, options }: { item: any; options: any }) => {
  const { pathname, search } = useLocation();
  const active = pathname.includes('/layout/block/') || new URLSearchParams(search).get('blockView') === 'empty';
  return (
    <a className={`${options.className || ''}${active ? ' p-menuitem-active' : ''}`} onClick={event => { event.preventDefault(); item.onBlockSelect?.(); }}>
      <span className={options.labelClassName}>{item.label}</span>
    </a>
  );
};

const alwaysExpandedBlockTemplate = (item: any, options: any) => <BlockNavigationItem item={item} options={options} />;

const sectionNavigationItems = [
  ['Sump', 'sump'], ['OHT', 'oht'], ['Roof', 'roof'], ['Floor Column', 'floor-column'],
  ['Stair Room', 'staircase/stair-room'], ['Head Room', 'staircase/head-room'],
  ['Lift Footing', 'lift/lift-footing'], ['Lift Shaft', 'lift/lift-shaft'],
  ['Machine Room', 'lift/machine-room'], ['Apartment', 'apartment'], ['OTS', 'ots'],
] as const;

const StableSectionNavigation = ({ blocks, blockName, selectedBlock, dispatch, navigate }: any) => {
  const { pathname } = useLocation();
  const blockList = blocks?.length ? blocks : [{ key: selectedBlock, descr: blockName }];
  return <div className="estimation-layout-stable-navigation">
    <div className="section-models-header p-panelmenu-header"><span className="p-menuitem-link"><strong>Section Models</strong></span></div>
    {blockList.map((block: any) => <div className="section-models-block" key={block.key ?? 'selected'}>
      <button type="button" className={`section-models-main p-menuitem-link${pathname.includes('/layout/block/') ? ' p-menuitem-active' : ''}`} onClick={() => { if (block.key !== null) { dispatch(setSelectedBlockReducer(block.key)); navigate(`/${MODULE_NAME}/layout/block/${block.key}?blockView=empty`); } }}>
        Block ({block.descr || blockName})
      </button>
      <div className="section-models-content p-panelmenu-content">
        {sectionNavigationItems.map(([label, path]) => <a key={path} href={`/${MODULE_NAME}/layout/${path}`} className={`p-menuitem-link${pathname.endsWith(`/layout/${path}`) ? ' p-menuitem-active' : ''}`} onClick={event => { event.preventDefault(); navigate(`/${MODULE_NAME}/layout/${path}`); }}>{label}</a>)}
      </div>
    </div>)}
  </div>;
};

const PortionNavigation = () => {
  const { pathname } = useLocation();
  const [searchParams, setSearchParams] = useSearchParams();
  const pathParts = pathname.split('/').filter(Boolean);
  const sectionKey = pathParts[pathParts.length - 1] === 'layout' ? 'apartment' : pathParts[pathParts.length - 1];
  const mappedPortions = useMemo(() => getMappedPortionTypes(sectionKey), [sectionKey]);
  const items = useMemo(() => portionItems.map(group => ({
    ...group,
    items: mappedPortions.length === 0 ? [{ label: 'No portions mapped', disabled: true }] : group.items.filter(item => mappedPortions.includes(portionKeyForLabel(item.label))).map((item, index) => ({
      ...item,
      className: `${(item as any).className || ''}${searchParams.get('portion') === portionKeyForLabel(item.label) || (!searchParams.get('portion') && index === 0) ? ' p-menuitem-active' : ''}`,
      command: () => {
        const next = new URLSearchParams(searchParams);
        next.set('portion', portionKeyForLabel(item.label));
        next.delete('blockView');
        setSearchParams(next);
      },
    })),
  })), [mappedPortions, searchParams, setSearchParams]);
  return <PanelMenu model={items} multiple style={{ width: '100%' }} className="pl-2" />;
};

const Main = () => {
  const { pathname } = useLocation();
  const navigate = useNavigate();
  const pathParts = pathname.split('/').filter(Boolean);
  const sectionKey = pathParts[pathParts.length - 1] === 'layout' ? 'apartment' : pathParts[pathParts.length - 1];
  const selectedProject = useAppSelector(selectSelectedProject);
  const selectedBlock = useAppSelector(selectSelectedBlock);
  const { data: blocks } = useBlocksForProjectQuery(
    { projectId: selectedProject },
    { skip: !selectedProject }
  );
  const blockName = blocks?.find(block => block.key === selectedBlock)?.descr || 'Select Block';
  const dispatch = useAppDispatch();
  const availableBlocks: Array<{ key: number | null; descr: string }> = useMemo(() => blocks && blocks.length > 0
    ? blocks.map(block => ({ key: block.key, descr: block.descr || blockName }))
    : [{ key: selectedBlock, descr: blockName }], [blocks, blockName, selectedBlock]);
  const sectionNavigation = useMemo(() => routes.map(group => ({
    ...group,
    key: 'section-models',
    items: availableBlocks.reduce<any[]>((items, block) => items.concat(group.items.map(mainItem => ({
      ...mainItem,
      key: 'section-main',
      label: `Block (${block.descr || blockName})`,
      className: (mainItem.className || '').replace(/\s*p-menuitem-active/g, ''),
      template: alwaysExpandedBlockTemplate,
      onBlockSelect: () => {
        if (block.key !== null) dispatch(setSelectedBlockReducer(block.key));
        if (block.key !== null) navigate(`/${MODULE_NAME}/layout/block/${block.key}?blockView=empty`);
      },
      // Keep the section tree stable while the route changes. Individual section
      // links derive their active state from the current location.
      items: mainItem.items || [],
    }))), []),
  })), [availableBlocks, blockName, dispatch, navigate]);
  // Keep the layout route element stable while only the nested workspace route changes.
  // Recreating this element makes React Router remount ModuleLayout and resets PanelMenu.
  const layoutElement = useMemo(
    () => <ModuleLayout navItems={sectionNavigation} panelMenu splitNavigation flushContent navigationSize={14} preserveNavigationModel primaryNavigationContent={<StableSectionNavigation blocks={blocks} blockName={blockName} selectedBlock={selectedBlock} dispatch={dispatch} navigate={navigate} />} secondaryNavigationContent={<PortionNavigation />} />,
    [sectionNavigation, blocks, blockName, selectedBlock, dispatch, navigate]
  );

  return (
  <>
  <Routes>
    <Route path="/" element={layoutElement}>
      <Route index element={<Navigate to="layout" replace />} />
      <Route path="layout" element={<MainPage />} />
      <Route path="layout/block/:blockKey" element={<MainPage />} />
      <Route path="layout/:section" element={<MainPage />} />
      <Route path="layout/:section/:subsection" element={<MainPage />} />
      <Route path="*" element={<NoMatch relative />} />
    </Route>
  </Routes>
  </>
);
};

export default Main;


