import React, { useCallback, useEffect, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import { Button } from 'primereact/button';
import { Tooltip } from 'primereact/tooltip';
import { useAuth } from '@igblsln/store';
import {
    useSendChatMessageMutation,
    ChatbotDisplay,
    ChatbotRequest,
    ChatbotResponse,
    DisplayColumn,
    DisplayRow
} from './api';

type ChatRole = 'user' | 'assistant' | 'divider';

interface ChatMessage {
    id: number;
    role: ChatRole;
    text: string;
    time: string;
    display?: ChatbotDisplay;
    confirmDetail?: string;
    confirmState?: 'pending' | 'confirmed' | 'cancelled';
}

//const WELCOME_TEXT = 'Hi! How can I help you today?';
const getWelcomeText = (name: string) => `Hi ${name}! How can I help you today?`;

const formatTime = (date: Date) =>
    date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

const isNumeric = (format?: string) => format === 'number' || format === 'currency';

const getCellValue = (row: DisplayRow, key: string): any =>
    key in row ? row[key] : key.split('.').reduce((acc: any, k) => acc?.[k], row);

const formatValue = (value: any, format?: string): string => {
    if (value === null || value === undefined || value === '') return '—';

    switch (format) {
        case 'currency':
            return Number.isNaN(Number(value))
                ? String(value)
                : Number(value).toLocaleString('en-IN', {
                      style: 'currency',
                      currency: 'INR',
                      maximumFractionDigits: 0
                  });
        case 'number':
            return Number.isNaN(Number(value)) ? String(value) : Number(value).toLocaleString('en-IN');
        case 'date': {
            const s = String(value);
            // date-only strings are parsed as local midnight to avoid off-by-one-day shifts
            const d = /^\d{4}-\d{2}-\d{2}$/.test(s) ? new Date(`${s}T00:00:00`) : new Date(s);
            return Number.isNaN(d.getTime())
                ? s
                : d.toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' });
        }
        default:
            return String(value);
    }
};

const DisplayTable = ({ columns, rows }: { columns: DisplayColumn[]; rows: DisplayRow[] }) => (
    <div className="chatbot-table-wrap">
        <table className="chatbot-table">
            <thead>
                <tr>
                    {columns.map((c) => (
                        <th key={c.key} className={isNumeric(c.format) ? 'is-num' : ''}>{c.label}</th>
                    ))}
                </tr>
            </thead>
            <tbody>
                {rows.map((row, i) => (
                    <tr key={i}>
                        {columns.map((c) => (
                            <td key={c.key} className={isNumeric(c.format) ? 'is-num' : ''}>
                                {formatValue(getCellValue(row, c.key), c.format)}
                            </td>
                        ))}
                    </tr>
                ))}
            </tbody>
        </table>
    </div>
);

// First column is used as the card heading, the rest as label/value rows
const DisplayCards = ({ columns, rows }: { columns: DisplayColumn[]; rows: DisplayRow[] }) => {
    const [titleCol, ...rest] = columns;
    return (
        <div className="chatbot-cards">
            {rows.map((row, i) => (
                <div key={i} className="chatbot-card">
                    <div className="chatbot-card-title">
                        {formatValue(getCellValue(row, titleCol.key), titleCol.format)}
                    </div>
                    {rest.map((c) => (
                        <div key={c.key} className="chatbot-card-row">
                            <span>{c.label}</span>
                            <strong>{formatValue(getCellValue(row, c.key), c.format)}</strong>
                        </div>
                    ))}
                </div>
            ))}
        </div>
    );
};

const ChatDisplay = ({ display, canLoadMore, loading, onLoadMore }: { display: ChatbotDisplay;
    canLoadMore: boolean;
    loading: boolean;
    onLoadMore: () => void;}) => {
    const { kind, title, total, columns, rows } = display;
    if (!columns?.length || !rows?.length) {
        return <div className="chatbot-display chatbot-display-empty">No records found.</div>;
    }
    const countLabel =
        typeof total === 'number' && total !== rows.length ? `${rows.length} of ${total}` : `${rows.length}`;

    return (
        <div className="chatbot-display">
            {title && (
                <div className="chatbot-display-title">
                    {title}
                    <span className="chatbot-display-count">{countLabel}</span>
                </div>
            )}
            {kind === 'card' ? (
                <DisplayCards columns={columns} rows={rows} />
            ) : (
                <DisplayTable columns={columns} rows={rows} />
            )}
            {display.has_more && canLoadMore && (
                <Button
                    label="Load more"
                    icon="pi pi-angle-down"
                    className="chatbot-load-more p-button-sm p-button-text"
                    disabled={loading}
                    onClick={onLoadMore}
                />
            )}
        </div>
    );
};
const ChatWidget = () => {
    const auth = useAuth();
    const userName = auth?.user?.user_name || 'there';
    const welcomeTime = useRef<string>(formatTime(new Date()));

    const [showNewChatMenu, setShowNewChatMenu] = useState<boolean>(false);
    const [isOpen, setIsOpen] = useState<boolean>(false);
    const [input, setInput] = useState<string>('');
    const [isTyping, setIsTyping] = useState<boolean>(false);
    const [messages, setMessages] = useState<ChatMessage[]>([]);
    const [convId, setconvId] = useState<string>('');
    const nextId = useRef<number>(1);
    const messagesEndRef = useRef<HTMLDivElement>(null);
    const inputRef = useRef<HTMLTextAreaElement>(null);
    const isMounted = useRef<boolean>(true);
    const lastMessageId = messages[messages.length - 1]?.id;
    
    const [sendChatMessage] = useSendChatMessageMutation();
    useEffect(() => {
        isMounted.current = true;
        return () => {
            isMounted.current = false;
        };
    }, []);

    // Auto-scroll to the latest message / typing indicator
    useEffect(() => {
        if (isOpen) {
            messagesEndRef.current?.scrollIntoView({ behavior: 'smooth', block: 'end' });
        }
    }, [messages, isTyping, isOpen]);

    // Focus input when the panel opens
    useEffect(() => {
        if (isOpen) {
            const t = window.setTimeout(() => inputRef.current?.focus(), 150);
            return () => window.clearTimeout(t);
        }
    }, [isOpen]);

    // Grow the textarea with its content (capped by CSS max-height)
    useEffect(() => {
        const el = inputRef.current;
        if (!el) return;
        el.style.height = 'auto';
        el.style.height = `${el.scrollHeight}px`;
    }, [input, isOpen]);

    // Close with Escape
    useEffect(() => {
        if (!isOpen) return;
        const onKey = (e: KeyboardEvent) => {
            if (e.key === 'Escape') setIsOpen(false);
        };
        document.addEventListener('keydown', onKey);
        return () => document.removeEventListener('keydown', onKey);
    }, [isOpen]);

    const addAssistantMessage = useCallback((partial: Partial<ChatMessage>) => {
    setMessages((prev) => [
        ...prev,
        { id: nextId.current++, role: 'assistant', text: '', time: formatTime(new Date()), ...partial }
    ]);
}, []);

// Turns an API response into an assistant message (table/cards and/or confirm card)
const appendResponse = useCallback(
    (response: ChatbotResponse) => {
        const needsConfirm = response.status === 'needs_confirmation';
        addAssistantMessage({
            text: response.reply,
            display: response.display ?? undefined,
            confirmDetail: needsConfirm ? (response.confirm ?? undefined) : undefined,
            confirmState: needsConfirm ? 'pending' : undefined
        });
    },
    [addAssistantMessage]
);

// Single place that talks to the API. Returns null on failure (error bubble already shown).
const callChatApi = useCallback(
    async (payload: Omit<ChatbotRequest, 'conversation_id'>): Promise<ChatbotResponse | null> => {
        setIsTyping(true);
        try {
            const response = await sendChatMessage({
                ...payload,
                ...(convId ? { conversation_id: convId } : {})
            }).unwrap();

            if (!isMounted.current) return null;
            if (response.conversation_id) {
                setconvId(response.conversation_id);
            }
            return response;
        } catch (err) {
            if (isMounted.current) {
                addAssistantMessage({ text: 'Sorry, something went wrong. Please try again.' });
            }
            return null;
        } finally {
            if (isMounted.current) setIsTyping(false);
        }
    },
    [convId, sendChatMessage, addAssistantMessage]
);

const handleSend = useCallback(async () => {
    const text = input.trim();
    if (!text || isTyping) return;

    setMessages((prev) => [
        ...prev,
        { id: nextId.current++, role: 'user', text, time: formatTime(new Date()) }
    ]);
    setInput('');

    const response = await callChatApi({ message: text });
    if (response) appendResponse(response);
}, [input, isTyping, callChatApi, appendResponse]);

// "Load more": the next rows are appended to the same table/cards
const handleLoadMore = async (messageId: number) => {
    if (isTyping) return;
    const response = await callChatApi({ action: 'next_page' });
    const next = response?.display;
    if (!next) return;

    setMessages((prev) =>
        prev.map((m) =>
            m.id === messageId && m.display
                ? {
                      ...m,
                      display: {
                          ...m.display,
                          rows: [...m.display.rows, ...next.rows],
                          total: next.total ?? m.display.total,
                          has_more: next.has_more
                      }
                  }
                : m
        )
    );
};

// Confirm / Cancel on a confirmation card
const handleConfirmAction = async (messageId: number, action: 'confirm' | 'cancel') => {
    if (isTyping) return;
    const response = await callChatApi({ action });
    if (!response) return; // card stays pending so the user can retry

    setMessages((prev) =>
        prev.map((m) =>
            m.id === messageId
                ? { ...m, confirmState: action === 'confirm' ? 'confirmed' : 'cancelled' }
                : m
        )
    );
    appendResponse(response);
};

    const startNewConversation = (clearMessages: boolean) => {
    if (isTyping) return; // don't reset while a reply is in flight

    setconvId('');
    setInput('');
    setShowNewChatMenu(false);

    if (clearMessages) {
        setMessages([]); // the welcome bubble is rendered separately, so it stays
    } else {
        // keep the history, but show where the new conversation starts
        setMessages((prev) => [
            ...prev,
            { id: nextId.current++, role: 'divider', text: 'New conversation started', time: formatTime(new Date()) }
        ]);
    }
};

    const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
        // Enter sends, Shift+Enter inserts a new line
        if (e.key === 'Enter' && !e.shiftKey && !e.nativeEvent.isComposing) {
            e.preventDefault();
            handleSend();
        }
    };

    const widget = (
        <>
            <Tooltip target=".chatbot-launcher" content="Chat with AI" position="left" />

            {isOpen && (
                <section className="chatbot-panel" role="dialog" aria-label="BuildIQ Assistant">
                    <header className="chatbot-header">
                        <div className="chatbot-header-avatar">
                            <i className="pi pi-sparkles" />
                        </div>
                        <div className="chatbot-header-info">
                            <h3 className="chatbot-header-title">BuildIQ Assistant</h3>
                            <span className="chatbot-header-status">
                                <span className="chatbot-status-dot" />
                                Online
                            </span>
                        </div>
                        <Button
                            icon="pi pi-plus"
                            className="chatbot-new-btn p-button-rounded p-button-text"
                            aria-label="New conversation"
                            title="New conversation"
                            disabled={isTyping}
                            onClick={() => setShowNewChatMenu((prev) => !prev)}
                        />
                        <Button
                            icon="pi pi-times"
                            className="chatbot-close-btn p-button-rounded p-button-text"
                            aria-label="Close chat"
                            onClick={() => setIsOpen(false)}
                        />
                    </header>
                    {showNewChatMenu && (
                            <div className="chatbot-newchat-menu">
                                <span>Start a new conversation?</span>
                                <div className="chatbot-newchat-actions">
                                    <Button
                                        label="Keep messages"
                                        className="p-button-sm p-button-outlined"
                                        disabled={isTyping}
                                        onClick={() => startNewConversation(false)}
                                    />
                                    <Button
                                        label="Clear messages"
                                        className="p-button-sm"
                                        disabled={isTyping}
                                        onClick={() => startNewConversation(true)}
                                    />
                                    <Button
                                        label="Cancel"
                                        className="p-button-sm p-button-text"
                                        onClick={() => setShowNewChatMenu(false)}
                                    />
                                </div>
                            </div>
                        )}

                    <div className="chatbot-messages" aria-live="polite">
                        <div className="chatbot-message chatbot-message-assistant">
    <div className="chatbot-bubble">{getWelcomeText(userName)}</div>
    <span className="chatbot-time">{welcomeTime.current}</span>
</div>
                        {messages.map((msg) => {
    if (msg.role === 'divider') {
        return (
            <div key={msg.id} className="chatbot-divider">
                <span>{msg.text}</span>
            </div>
        );
    }

    const isLatest = msg.id === lastMessageId;

    return (
        <div
            key={msg.id}
            className={`chatbot-message chatbot-message-${msg.role}${
                msg.display || msg.confirmState ? ' chatbot-message-wide' : ''
            }`}
        >
            {msg.confirmState ? (
                <div className="chatbot-confirm-card">
                    <div className="chatbot-confirm-header">
                        <i className="pi pi-exclamation-circle" />
                        Confirmation required
                    </div>
                    {msg.text && <p className="chatbot-confirm-text">{msg.text}</p>}
                    
                    {msg.confirmState === 'pending' && isLatest ? (
                        <div className="chatbot-confirm-actions">
                            <Button
                                label="Confirm"
                                icon="pi pi-check"
                                className="p-button-sm"
                                disabled={isTyping}
                                onClick={() => handleConfirmAction(msg.id, 'confirm')}
                            />
                            <Button
                                label="Cancel"
                                icon="pi pi-times"
                                className="p-button-sm p-button-outlined p-button-secondary"
                                disabled={isTyping}
                                onClick={() => handleConfirmAction(msg.id, 'cancel')}
                            />
                        </div>
                    ) : (
                        <div className="chatbot-confirm-result">
                            {msg.confirmState === 'confirmed'
                                ? 'Confirmed'
                                : msg.confirmState === 'cancelled'
                                ? 'Cancelled'
                                : 'Expired'}
                        </div>
                    )}
                </div>
            ) : (
                msg.text && <div className="chatbot-bubble">{msg.text}</div>
            )}

            {msg.display && (
                <ChatDisplay
                    display={msg.display}
                    canLoadMore={isLatest}
                    loading={isTyping}
                    onLoadMore={() => handleLoadMore(msg.id)}
                />
            )}
            <span className="chatbot-time">{msg.time}</span>
        </div>
    );
})}

                        {isTyping && (
                            <div className="chatbot-message chatbot-message-assistant">
                                <div className="chatbot-bubble chatbot-typing" aria-label="Assistant is typing">
                                    <span />
                                    <span />
                                    <span />
                                </div>
                            </div>
                        )}
                        <div ref={messagesEndRef} />
                    </div>

                    <footer className="chatbot-input-area">
                        <textarea
                            ref={inputRef}
                            value={input}
                            onChange={(e) => setInput(e.target.value)}
                            onKeyDown={handleKeyDown}
                            rows={1}
                            placeholder="Type your message..."
                            className="chatbot-input p-inputtext p-component"
                            aria-label="Message"
                        />
                        <Button
                            icon="pi pi-send"
                            className="chatbot-send-btn p-button-rounded"
                            aria-label="Send message"
                            disabled={!input.trim() || isTyping}
                            onClick={handleSend}
                        />
                    </footer>
                </section>
            )}

            <Button
                icon={isOpen ? 'pi pi-chevron-down' : 'pi pi-comments'}
                className={`chatbot-launcher p-button-rounded${isOpen ? ' chatbot-launcher-open' : ''}`}
                aria-label={isOpen ? 'Close chat' : 'Open chat'}
                aria-expanded={isOpen}
                onClick={() => setIsOpen((prev) => !prev)}
            />
        </>
    );

    // Portal to <body> so the widget is never clipped by the Dashboard's scroll container
    // and never affects the Dashboard layout.
    return createPortal(widget, document.body);
};

export default ChatWidget;
